export class AlreadyArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * The instant at or before which a row archived under a `retentionDays` window
 * has expired. The restore guard and the retention sweep both read it from
 * here, so they agree on the edge.
 */
export function retentionCutoff(now: Date, retentionDays: number): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

/** True once an archived row was archived at or before the cut-off. */
export function isExpired(row: SoftDeletable, cutoff: IsoTimestamp): boolean {
  return row.archivedAt !== null && row.archivedAt <= cutoff;
}

/** Why a restore was refused. A refused restore leaves the row untouched. */
export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

const REFUSAL_DETAIL: Readonly<Record<RestoreRefusalReason, string>> = {
  not_archived: "it is not archived",
  expired: "its retention window has passed",
  project_archived: "its project is archived",
  quota: "its project is at the plan's issue quota",
};

export class RestoreRefusedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: RestoreRefusalReason) {
    super(`Cannot restore the issue: ${REFUSAL_DETAIL[reason]}.`);
    this.name = "RestoreRefusedError";
  }
}

