/**
 * Next per-project issue number. Archived issues keep their number, so the max
 * is taken over every row rather than the live ones. Purged numbers are no
 * longer in any row, which is what the project's mark covers.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return Math.max(row?.value ?? 0, readIssueNumberMark(db, orgId, projectId)) + 1;
}

function readIssueNumberMark(
  db: Db,
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const row = db
    .select({ value: issueNumberMarks.lastNumber })
    .from(issueNumberMarks)
    .where(
      and(
        orgPredicate(issueNumberMarks.orgId, orgId),
        eq(issueNumberMarks.projectId, projectId),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** Lifts the project's mark to its highest number in use; runs before a purge deletes rows. */
function raiseIssueNumberMark(
  db: Db,
  orgId: OrgId,
  projectId: ProjectId,
): void {
  const top = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const lastNumber = Math.max(
    top?.value ?? 0,
    readIssueNumberMark(db, orgId, projectId),
  );

  db.insert(issueNumberMarks)
    .values({ orgId, projectId, lastNumber })
    .onConflictDoUpdate({
      target: issueNumberMarks.projectId,
      set: { lastNumber },
    })
    .run();
}

