/**
 * Archived issues archived at or before `cutoff`, in every project of the org.
 * A purge deletes what it is handed, so callers ask again until none are left.
 */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  limit: number,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .orderBy(issues.archivedAt)
    .limit(limit)
    .all();

  return rows.map((row) => toIssue(row));
}

/** What a purge removed that the caller still has to clean up outside this table. */
export interface PurgedIssues {
  readonly commentIds: readonly CommentId[];
  /** Megabytes the purged attachments were counted for, each rounded up. */
  readonly storageMb: number;
}

const BYTES_PER_MB = 1024 * 1024;

/**
 * Hard-deletes issues together with their label links, comments and
 * attachments, in one transaction. Each project touched has its number mark
 * raised before any row goes, so a purged number is never handed out again.
 */
export async function purgeIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<PurgedIssues> {
  const ids = [...issueIds];

  return getDb().transaction((tx) => {
    const touched = tx
      .selectDistinct({ projectId: issues.projectId })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .all();
    for (const { projectId } of touched) {
      raiseIssueNumberMark(tx, orgId, projectId as ProjectId);
    }

    const commentRows = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)),
      )
      .all();
    const attachmentRows = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.issueId, ids),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .run();

    return {
      commentIds: commentRows.map((row) => row.id as CommentId),
      storageMb: attachmentRows.reduce(
        (total, row) => total + Math.ceil(row.sizeBytes / BYTES_PER_MB),
        0,
      ),
    };
  });
}

