/**
 * Permanently removes archived issues and audit rows once the plan's `retentionDays` have passed.
 *
 * Must call (do not reimplement): getPlanLimits, retentionCutoff
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { retentionCutoff } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { IsoTimestamp, OrgId } from "@/types/common";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Archived issues are kept for as long as the plan promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * An expired issue is deleted outright, with its label links, comments and attachments, and its search documents go with it. The storage its
 * attachments were counted for is given back; the issues-used counter is left alone, because archived issues were never counted in it. The
 * audit rows past the window are purged as well.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const cutoff = retentionCutoff(now, getPlanLimits(org.plan).retentionDays);

      try {
        result.processed += await purgeExpiredIssues(orgId, cutoff);
      } catch (error) {
        result.failed += 1;
        logger.error("issue purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Purges every expired issue of the org, in every project. Each page is deleted before the next is read, so asking again
 * for the first page walks through the rest, however many there are.
 */
async function purgeExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<number> {
  let purged = 0;

  for (;;) {
    const batch = await issueRepo.listExpiredIssues(orgId, cutoff, PAGE_SIZE);
    if (batch.length === 0) return purged;

    const removed = await issueRepo.purgeIssues(
      orgId,
      batch.map((issue) => issue.id),
    );

    for (const issue of batch) {
      await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
    }
    for (const commentId of removed.commentIds) {
      await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
    }
    if (removed.storageMb > 0) {
      await usageRepo.incrementUsage(orgId, {
        storageMbUsed: -removed.storageMb,
      });
    }

    purged += batch.length;
  }
}

