      }
    }
  });
}

/**
 * Purges every expired issue of the org, in every project. Each page is deleted before the next is read, so asking again
 * for the first page walks through the rest, however many there are.
 */
async function purgeExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<number> {
  let purged = 0;

  for (;;) {
    const batch = await issueRepo.listExpiredIssues(orgId, cutoff, PAGE_SIZE);
    if (batch.length === 0) return purged;

    const removed = await issueRepo.purgeIssues(
      orgId,
      batch.map((issue) => issue.id),
    );

    for (const issue of batch) {
      await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
    }
    for (const commentId of removed.commentIds) {
      await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
    }
    if (removed.storageMb > 0) {
      await usageRepo.incrementUsage(orgId, {
        storageMbUsed: -removed.storageMb,
      });
    }

    purged += batch.length;
  }
}

