/**
 * The issue trash. An archived issue can be restored while its plan's retention
 * window is open; once the window has passed it is expired, and the retention
 * sweep deletes it, with everything that hangs off it, for good.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { RestoreRefusedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { runCleanupArchivedJob } from "@/server/jobs";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as activityService from "@/server/services/activity-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { IssueId } from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Unsubscribe } from "@/types/event";

const DAY_MS = 24 * 60 * 60 * 1000;
const MIB = 1024 * 1024;
/** The free plan keeps archived issues for 30 days. */
const RETENTION_MS = 30 * DAY_MS;
const ARCHIVED_AT = new Date("2026-06-01T12:00:00.000Z");

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  // Only `Date` is faked: every write stamps the instant the test has set.
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(ARCHIVED_AT);

  tenant = await createTenant("trash", "free");

  detachers.push(
    usageService.registerUsageListeners(),
    searchService.registerSearchListeners(),
    activityService.registerActivityListeners(),
  );
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
  cleanup();
});

/** Creates an issue and archives it as of `at`, leaving the clock there. */
async function archivedAt(
  at: Date,
  title: string,
  owner: Tenant = tenant,
): Promise<Issue> {
  vi.setSystemTime(at);
  const issue = await issueService.createIssue(
    owner.actors.member,
    issueInput(owner.org.id, owner.project.id, { title }),
  );
  return issueService.archiveIssue(owner.actors.member, owner.org.id, issue.id);
}

function restore(issueId: IssueId, owner: Tenant = tenant) {
  return issueService.restoreIssue(owner.actors.member, owner.org.id, issueId);
}

describe("restoring an archived issue", () => {
  it("brings the issue back with its number, counter, search entry and audit row", async () => {
    const archived = await archivedAt(ARCHIVED_AT, "Restorable trash marker");
    vi.setSystemTime(new Date(ARCHIVED_AT.getTime() + 29 * DAY_MS));

    const usedBefore = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;
    const seen: unknown[] = [];
    const off = subscribe("issue.restored", (payload) => {
      seen.push(payload);
    });

    try {
      const restored = await restore(archived.id);

      expect(restored.archivedAt).toBeNull();
      expect(restored.number).toBe(archived.number);
      expect(seen).toEqual([
        expect.objectContaining({
          issueId: archived.id,
          projectId: tenant.project.id,
        }),
      ]);
    } finally {
      off();
    }

    await expect(usageRepo.getUsage(tenant.org.id)).resolves.toMatchObject({
      issuesUsed: usedBefore + 1,
    });

    const hits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Restorable trash marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(1);

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });
    expect(audit.items).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ action: "issue.restored", subjectId: archived.id }),
      ]),
    );
  });

  it("refuses a live issue as not archived, changing nothing", async () => {
    vi.setSystemTime(ARCHIVED_AT);
    const live = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Still live" }),
    );

    await expect(restore(live.id)).rejects.toBeInstanceOf(RestoreRefusedError);
    await expect(restore(live.id)).rejects.toMatchObject({
      code: "conflict",
      reason: "not_archived",
    });
  });

  it("keeps the window open until exactly retentionDays have passed", async () => {
    const early = await archivedAt(ARCHIVED_AT, "Window open marker");
    const late = await archivedAt(ARCHIVED_AT, "Window closed marker");
    const edge = new Date(ARCHIVED_AT.getTime() + RETENTION_MS);

    vi.setSystemTime(new Date(edge.getTime() - 1));
    await expect(restore(early.id)).resolves.toMatchObject({ archivedAt: null });

    vi.setSystemTime(edge);
    await expect(restore(late.id)).rejects.toMatchObject({ reason: "expired" });

    const stillArchived = await issueRepo.findIssueById(tenant.org.id, late.id);
    expect(stillArchived?.archivedAt).toBe(late.archivedAt);
  });

  it("refuses while the issue's project is archived", async () => {
    const owner = await createTenant("trashproject", "growth");
    const archived = await archivedAt(ARCHIVED_AT, "Project trash marker", owner);

    await projectService.archiveProject(owner.actors.admin, {
      orgId: owner.org.id,
      projectId: owner.project.id,
      archiveIssues: false,
    });

    await expect(restore(archived.id, owner)).rejects.toMatchObject({
      reason: "project_archived",
    });
  });

  it("refuses when the project is at the plan's per-project issue quota", async () => {
    const owner = await createTenant("trashquota", "free");
    const archived = await archivedAt(ARCHIVED_AT, "Quota trash marker", owner);

    // Fill the project to the free plan's 100 live issues.
    for (let number = archived.number + 1; number <= archived.number + 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(owner.org.id, owner.project.id, { title: `Filler ${number}` }),
        owner.userIds.member,
        number,
      );
    }

    await expect(restore(archived.id, owner)).rejects.toMatchObject({
      reason: "quota",
    });
  });

  it("needs the archive permission, and stays inside the caller's organization", async () => {
    const archived = await archivedAt(ARCHIVED_AT, "Permission trash marker");
    vi.setSystemTime(new Date(ARCHIVED_AT.getTime() + DAY_MS));

    await expect(
      issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, archived.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const elsewhere = await createTenant("trashelsewhere", "free");
    await expect(
      issueService.restoreIssue(elsewhere.actors.admin, tenant.org.id, archived.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.restoreIssue(tenant.actors.admin, tenant.org.id, "01MISSING" as IssueId),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

