      contentType: "application/pdf",
      sizeBytes: 1.5 * MIB,
    });
    await attachmentService.addAttachment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doomed.id,
      filename: "photo.png",
      contentType: "image/png",
      sizeBytes: 3 * MIB,
    });

    await archivedAt(ARCHIVED_AT, "Sweep doomed archive marker").catch(() => undefined);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, doomed.id);
    vi.setSystemTime(new Date(ARCHIVED_AT.getTime() + 20 * DAY_MS));
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, kept.id);

    const before = await usageRepo.getUsage(tenant.org.id);
    const commentHitsBefore = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Sweep comment marker",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(commentHitsBefore.total).toBe(1);

    const now = new Date(ARCHIVED_AT.getTime() + 31 * DAY_MS);
    const result = await runCleanupArchivedJob(now);
    expect(result.failed).toBe(0);

    await expect(issueRepo.findIssueById(tenant.org.id, doomed.id)).resolves.toBeNull();
    await expect(commentRepo.listThread(tenant.org.id, doomed.id)).resolves.toEqual([]);
    await expect(
      attachmentRepo.listAttachments(tenant.org.id, doomed.id),
    ).resolves.toEqual([]);
    const labelsLeft = await labelRepo.listLabelsForIssues(tenant.org.id, [doomed.id]);
    expect(labelsLeft[doomed.id] ?? []).toEqual([]);

    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.storageMbUsed).toBe(before.storageMbUsed - 5);
    expect(after.issuesUsed).toBe(before.issuesUsed);

    const commentHitsAfter = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Sweep comment marker",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(commentHitsAfter.total).toBe(0);

    // Still inside its own window at the sweep's instant, so it survives.
    await expect(issueRepo.findIssueById(tenant.org.id, kept.id)).resolves.not.toBeNull();
    await expect(restore(kept.id)).resolves.toMatchObject({ archivedAt: null });

    await expect(restore(doomed.id)).rejects.toBeInstanceOf(NotFoundError);

    // The purged issue held the highest number, and it must not come back.
    vi.setSystemTime(now);
    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the purge" }),
    );
    expect(next.number).toBe(doomed.number + 1);
  });

  it("purges every expired issue of the workspace, not only the first page", async () => {
    const bulk = await createTenant("trashbulk", "free");
    const EXPIRED = 130;

    vi.setSystemTime(ARCHIVED_AT);
    for (let number = 1; number <= EXPIRED; number += 1) {
      const issue = await issueRepo.insertIssue(
        issueInput(bulk.org.id, bulk.project.id, { title: `Bulk ${number}` }),
        bulk.userIds.member,
        number,
      );
      await issueRepo.archiveIssue(bulk.org.id, issue.id);
    }
    // The sweep only visits workspaces that have a usage row.
    await usageRepo.getUsage(bulk.org.id);

    const result = await runCleanupArchivedJob(
      new Date(ARCHIVED_AT.getTime() + RETENTION_MS + DAY_MS),
    );
    expect(result.failed).toBe(0);

    const left = await issueRepo.listIssues({
      orgId: bulk.org.id,
      limit: 25,
      cursor: null,
      includeArchived: true,
    });
    expect(left.total).toBe(0);
  });
});

